using System.Diagnostics;
using System.Text;
using System.Text.Json;
using ModelContextProtocol.Client;
namespace ProjectDesk;

public sealed class AiCodexClient {
 private readonly Func<string,string[],string?,string,CancellationToken,Task<(int Code,string Output,string Error)>> _run;
 public AiCodexClient():this(Run){}
 internal AiCodexClient(Func<string,string[],string?,string,CancellationToken,Task<(int Code,string Output,string Error)>> run){_run=run;}
 public async Task LoginAsync(string executable,CancellationToken token){var profile=new AiConnectionProfile(Guid.NewGuid().ToString(),AiProvider.OpenAI,AiConnectionMode.CodexSubscription,Executable:executable);profile.Validate(true);string folder=Path.Combine(Path.GetTempPath(),AppBrand.Name,"login-"+Guid.NewGuid());Directory.CreateDirectory(folder);try{var result=await _run(executable,["login"],null,folder,token);if(result.Code!=0)throw new InvalidOperationException("Codex sign-in did not finish. Try codex login in your terminal.");}finally{try{Directory.Delete(folder,false);}catch(IOException){}catch(UnauthorizedAccessException){}}}
 public static string ExecutableName=>OperatingSystem.IsWindows()?"codex.exe":"codex";
 public static string? FindExecutable()=>OperatingSystem.IsWindows()?FindWindowsExecutable():FindUnixExecutable(UnixSearchFolders());
 private static string? FindWindowsExecutable(){foreach(var folder in (Environment.GetEnvironmentVariable("PATH")??"").Split(Path.PathSeparator)){string file=Path.Combine(folder,"codex.exe");if(File.Exists(file))return Path.GetFullPath(file);}string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"OpenAI","Codex","bin");if(Directory.Exists(root))foreach(var folder in Directory.GetDirectories(root).OrderByDescending(Directory.GetLastWriteTimeUtc)){string file=Path.Combine(folder,"codex.exe");if(File.Exists(file))return file;}return null;}
 // Apps started from Finder get a minimal PATH, so also look where Homebrew, npm and user installs put codex.
 private static IEnumerable<string> UnixSearchFolders(){string home=Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);return (Environment.GetEnvironmentVariable("PATH")??"").Split(Path.PathSeparator,StringSplitOptions.RemoveEmptyEntries).Concat(["/opt/homebrew/bin","/usr/local/bin",Path.Combine(home,".local","bin")]).Distinct();}
 // Returns the native codex binary. An npm install exposes a Node.js launcher, so use the native binary it bundles.
 internal static string? FindUnixExecutable(IEnumerable<string> folders){
  string arch=System.Runtime.InteropServices.RuntimeInformation.OSArchitecture==System.Runtime.InteropServices.Architecture.Arm64?"arm64":"x64";
  string triple=OperatingSystem.IsMacOS()?(arch=="arm64"?"aarch64":"x86_64")+"-apple-darwin":(arch=="arm64"?"aarch64":"x86_64")+"-unknown-linux-musl";
  string platformPackage=(OperatingSystem.IsMacOS()?"codex-darwin-":"codex-linux-")+arch;
  foreach(var folder in folders){string file=Path.Combine(folder,"codex");if(!File.Exists(file))continue;
   string target=new FileInfo(file).ResolveLinkTarget(true)?.FullName??Path.GetFullPath(file);if(IsNativeExecutable(target))return target;
   string? package=Path.GetDirectoryName(Path.GetDirectoryName(target));if(package==null)continue;
   foreach(var candidate in new[]{Path.Combine(package,"node_modules","@openai",platformPackage,"vendor",triple,"bin","codex"),Path.Combine(package,"vendor",triple,"bin","codex")})if(IsNativeExecutable(candidate))return candidate;}
  return null;
 }
 private static bool IsNativeExecutable(string path){try{if(!File.Exists(path))return false;Span<byte> magic=stackalloc byte[4];using var stream=File.OpenRead(path);if(stream.Read(magic)<4)return false;uint value=System.Buffers.Binary.BinaryPrimitives.ReadUInt32BigEndian(magic);return value is 0xFEEDFACF or 0xCFFAEDFE or 0xFEEDFACE or 0xCEFAEDFE or 0xCAFEBABE or 0x7F454C46;}catch(IOException){return false;}catch(UnauthorizedAccessException){return false;}}
 public static string[] Arguments(AiConnectionProfile profile)=>new[]{"exec","--sandbox","read-only","--ephemeral","--skip-git-repo-check","--ignore-user-config","--disable","shell_tool","--disable","view_image","--disable","apps","--disable","plugins","--disable","multi_agent","--disable","browser_use","--disable","computer_use","--disable","code_mode_host","-c","web_search=\"disabled\"","--json","--color","never"}.Concat(string.IsNullOrWhiteSpace(profile.Model)?[]:new[]{"--model",profile.Model}).Append("-").ToArray();
 public async Task<AiReply> SendAsync(AiConnectionProfile profile,IReadOnlyList<AiMessage> messages,CancellationToken token){profile.Validate(true);AiProviderClient.ValidateMessages(messages);string folder=Path.Combine(Path.GetTempPath(),AppBrand.Name,"ai-"+Guid.NewGuid());Directory.CreateDirectory(folder);try{var status=await _run(profile.Executable!,["login","status"],null,folder,token);if(status.Code!=0||!(status.Output+status.Error).Contains("ChatGPT",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Sign in to the official Codex CLI with ChatGPT first. Planora will not use an API-key CLI login for subscription mode.");string input=AiProviderClient.Instructions+"\n\nThis is a text-only planning conversation. Work only from the supplied messages. Do not call tools, read files or execute commands.\n"+JsonSerializer.Serialize(messages);var result=await _run(profile.Executable!,Arguments(profile),input,folder,token);if(result.Code!=0)throw new InvalidOperationException("Codex did not complete the request. Check sign-in, CLI version, model access and subscription limits.");return Parse(result.Output,profile.Model);}finally{try{Directory.Delete(folder,false);}catch(IOException){}catch(UnauthorizedAccessException){}}}
 public static AiReply Parse(string jsonl,string model){string? text=null;long? input=null,output=null;foreach(var line in jsonl.Split('\n',StringSplitOptions.RemoveEmptyEntries)){using var json=JsonDocument.Parse(line);var root=json.RootElement;string type=root.GetProperty("type").GetString()??"";if(type is "error" or "turn.failed")throw new InvalidDataException("The Codex request failed. Check your CLI session.");if(type=="item.completed"&&root.TryGetProperty("item",out var item)&&item.GetProperty("type").GetString()=="agent_message")text=item.GetProperty("text").GetString();if(type=="turn.completed"&&root.TryGetProperty("usage",out var usage)){if(usage.TryGetProperty("input_tokens",out var i))input=i.GetInt64();if(usage.TryGetProperty("output_tokens",out var o))output=o.GetInt64();}}if(string.IsNullOrWhiteSpace(text))throw new InvalidDataException("Codex returned no assistant text.");return new(text,model.Length==0?"Codex account default":model,input,output);}
 internal static async Task<(int Code,string Output,string Error)> Run(string executable,string[] args,string? input,string directory,CancellationToken token){var info=new ProcessStartInfo(executable){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=directory,StandardInputEncoding=new UTF8Encoding(false)};foreach(var arg in args)info.ArgumentList.Add(arg);info.Environment.Clear();foreach(var pair in StdioClientTransportOptions.GetDefaultEnvironmentVariables())info.Environment[pair.Key]=pair.Value;foreach(var key in new[]{"HOME","CODEX_HOME"})if(Environment.GetEnvironmentVariable(key)is string value)info.Environment[key]=value;using var process=new Process{StartInfo=info};if(!process.Start())throw new IOException("Could not start the configured Codex executable.");void Stop(){try{if(!process.HasExited)process.Kill(entireProcessTree:true);}catch(InvalidOperationException){}}using var reading=CancellationTokenSource.CreateLinkedTokenSource(token);using var stop=token.Register(Stop);async Task<string> Guard(StreamReader reader){try{return await Read(reader,reading.Token);}catch{Stop();throw;}}var stdout=Guard(process.StandardOutput);var stderr=Guard(process.StandardError);try{if(input!=null)await process.StandardInput.WriteAsync(input.AsMemory(),token);process.StandardInput.Close();await process.WaitForExitAsync(token);return(process.ExitCode,await stdout,await stderr);}catch{token.ThrowIfCancellationRequested();throw;}finally{if(!process.HasExited){Stop();await process.WaitForExitAsync();}reading.Cancel();try{await Task.WhenAll(stdout,stderr).WaitAsync(TimeSpan.FromSeconds(1));}catch{}}}
 private static async Task<string> Read(StreamReader reader,CancellationToken token){var text=new StringBuilder();var chars=new char[4096];int count;while((count=await reader.ReadAsync(chars,token))>0){if(text.Length+count>2*1024*1024)throw new InvalidDataException("Codex output exceeds 2 MiB.");text.Append(chars,0,count);}return text.ToString();}
}
